import React, { useState, useEffect, useContext } from "react";
import jsPDF from "jspdf";
import autoTable from "jspdf-autotable"; 
import axios from "axios";
import { Link, useNavigate } from "react-router-dom";
import SearchBar from "./SearchBar";
import { OrderContext } from "./OrderContext";

const AllOrders = () => {
  const [orders, setOrders] = useState([]);
  const [searchQuery, setSearchQuery] = useState("");
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();
  const { ordersChanged, setOrdersChanged } = useContext(OrderContext);

  useEffect(() => {
    const fetchOrders = async () => {
      try {
        setLoading(true);
        const res = await axios.get("http://localhost:5000/orders/");
        setOrders(res.data.orders || []);
      } catch (err) {
        console.error("Error fetching orders:", err);
      } finally {
        setLoading(false);
      }
    };
    fetchOrders();
  }, [ordersChanged]);

  const filterOrders = orders.filter((order) =>
    Object.values(order).some((value) =>
      String(value).toLowerCase().includes(searchQuery.toLowerCase())
    )
  );

  const generateReport = () => {
    const doc = new jsPDF();

    if (filterOrders.length === 0) {
      alert("No orders available for the report.");
      return;
    }

    doc.text("Order Management Report", 14, 16);
    const columns = ["First Name", "Last Name", "Email", "Phone", "Address", "City", "Order ID", "Instructions", "Pickup Time", "Status"];

    const rows = filterOrders.map((order) => [
      order?.firstName || "N/A",
      order?.lastName || "N/A",
      order?.email || "N/A",
      order?.phoneNumber || "N/A",
      order?.address || "N/A",
      order?.city || "N/A",
      order?.orderId || "N/A",
      order?.specialInstructions || "N/A",
      order?.pickupTime || "N/A",
      order?.orderStatus || "N/A",
    ]);

    autoTable(doc, { head: [columns], body: rows, startY: 22 });
    doc.save("Orders_report.pdf");
  };

  const handleDelete = async (orderId) => {
    if (!window.confirm("Are you sure you want to delete this order?")) return;

    try {
      await axios.delete(`http://localhost:5000/orders/${orderId}`);
      setOrders((prevOrders) => prevOrders.filter((order) => order._id !== orderId));
      setOrdersChanged((prev) => !prev);
      alert("Order deleted successfully!");
    } catch (error) {
      console.error("Error deleting order:", error);
      alert("Failed to delete the order. Try again.");
    }
  };

  return (
    <div style={{ padding: "20px", backgroundColor: "#f3f4f6", minHeight: "100vh" }}>
      <h1 style={{ textAlign: "center", fontSize: "2.25rem", fontWeight: "bold", marginBottom: "1.5rem" }}>All Orders</h1>
      <div style={{ display: "flex", justifyContent: "center", marginBottom: "20px" }}>
        <SearchBar onSearch={setSearchQuery} />
      </div>

      {loading ? (
        <div style={{ textAlign: "center", padding: "20px" }}>Loading orders...</div>
      ) : (
        <table style={{ width: "100%", borderCollapse: "collapse", backgroundColor: "#fff", textAlign: "left" }}>
          <thead>
            <tr style={{ backgroundColor: "#ddd" }}>
              {["First Name", "Last Name", "Email", "Phone", "Address", "City", "Order ID", "Instructions", "Pickup Time", "Status", "Actions"].map((header) => (
                <th key={header} style={{ padding: "10px", borderBottom: "2px solid #ccc" }}>{header}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {filterOrders.length > 0 ? (
              filterOrders.map((order) => (
                <tr key={order._id} style={{ borderBottom: "1px solid #ddd" }}>
                  {[order.firstName, order.lastName, order.email, order.phoneNumber, order.address, order.city, order.orderId, order.specialInstructions, order.pickupTime, order.orderStatus].map((value, index) => (
                    <td key={index} style={{ padding: "10px" }}>{value || "N/A"}</td>
                  ))}
                  <td style={{ padding: "10px" }}>
                    <Link to={`/update-order/${order._id}`} style={{ backgroundColor: "#dc2626", color: "#fff", padding: "6px 12px", borderRadius: "4px", textDecoration: "none", marginRight: "10px" }}>Update</Link>
                    <button onClick={() => handleDelete(order._id)} style={{ backgroundColor: "black", color: "#fff", padding: "6px 12px", borderRadius: "4px", cursor: "pointer" }}>Delete</button>
                  </td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan="11" style={{ textAlign: "center", padding: "10px" }}>No orders available</td>
              </tr>
            )}
          </tbody>
        </table>
      )}

      <div style={{ textAlign: "center", marginTop: "20px" }}>
        <button onClick={generateReport} style={{ padding: "12px 20px", backgroundColor: "black", color: "white", borderRadius: "5px", cursor: "pointer", width: "200px", marginBottom: "15px" }}>Generate Report</button>
        <button onClick={() => navigate("/")} style={{ padding: "12px 20px", backgroundColor: "#dc2626", color: "white", borderRadius: "5px", cursor: "pointer", width: "200px" }}>Back to Home</button>
      </div>
    </div>
  );
};

export default AllOrders;
